    'admin.s95': { 'zh-Hant': '貼圖碎片', 'en': 'Sticker fragments', 'yue': '貼圖碎片' },
    'admin.s96': { 'zh-Hant': '學生扭到已擁有的貼圖會自動轉為碎片；碎片可兌換未擁有的貼圖（只限開放中的系列）。', 'en': 'When a student draws a sticker they already own, it turns into fragments; fragments can be exchanged for stickers they don\'t own (open series only).', 'yue': '學生扭到已擁有的貼圖會自動轉為碎片；碎片可兌換未擁有的貼圖（只限開放中的系列）。' },
    'admin.s97': { 'zh-Hant': '重複時得到碎片', 'en': 'Fragments for a duplicate', 'yue': '重複時得到碎片' },
    'admin.s98': { 'zh-Hant': '兌換所需碎片', 'en': 'Fragments needed to exchange', 'yue': '兌換所需碎片' },
    'admin.s99': { 'zh-Hant': '還原未儲存的改動', 'en': 'Revert unsaved changes', 'yue': '還原未儲存的改動' },
    'admin.s102': { 'zh-Hant': '把已上傳的貼圖、扭蛋機圖及背景圖轉為 WebP 格式，檔案細約九成。執行前請先儲存改動。可重複執行，已壓縮的會略過。', 'en': 'Converts uploaded stickers, machine images and backgrounds to WebP, about 90% smaller. Save your changes first. Can be run again; already-compressed images are skipped.', 'yue': '把已上傳的貼圖、扭蛋機圖及背景圖轉為 WebP 格式，檔案細約九成。執行前請先儲存改動。可重複執行，已壓縮的會略過。' },
    'admin.s105': { 'zh-Hant': '已新增系列（預設未開放扭蛋），請點擊「儲存全部改動」', 'en': 'Series added (closed for draws by default). Click "Save all changes".', 'yue': '已新增系列（預設未開放扭蛋），請點擊「儲存全部改動」' },
