    'admin.s125': { 'zh-Hant': '已調整；部分系列權重全部是 0，未有調整', 'en': 'Adjusted; some series have all weights at 0 and were not adjusted', 'yue': '已調整；部分系列權重全部是 0，未有調整' },
    'admin.s126': { 'zh-Hant': '已將每個系列的權重調整為合計 100', 'en': 'Each series\' weights now total 100', 'yue': '已將每個系列的權重調整為合計 100' },
    'admin.s128': { 'zh-Hant': '確定刪除這張貼圖？若已經有用戶擁有，其收集紀錄會保留，但在圖鑑中將不再顯示。', 'en': 'Delete this sticker? Users who own it keep their records, but it won\'t be shown in the collection any more.', 'yue': '確定刪除這張貼圖？若已經有用戶擁有，其收集紀錄會保留，但在圖鑑中將不再顯示。' },
    'admin.s129': { 'zh-Hant': '重新排序編號會將貼紙 id 由 1 開始重新連續編號。\n\n如果已經有真實學生使用這個扭蛋機扭過蛋、收藏了某幾隻貼紙，他們原有的收藏會因為編號改變而對應不上（貼紙會「變成另一隻」）。如果尚未有學生正式使用過，或者你願意接受洗牌整批收藏記錄，才繼續。\n\n確定要重新編號？', 'en': 'Renumbering gives stickers new consecutive ids starting from 1.\n\nIf real students have already drawn and collected some stickers, their collections won\'t match the new numbers (a sticker "becomes a different one"). Continue only if no students have used it yet, or you accept reshuffling all collection records.\n\nRenumber now?', 'yue': '重新排序編號會將貼紙 id 由 1 開始重新連續編號。\n\n如果已經有真實學生使用這個扭蛋機扭過蛋、收藏了某幾隻貼紙，他們原有的收藏會因為編號改變而對應不上（貼紙會「變成另一隻」）。如果尚未有學生正式使用過，或者你願意接受洗牌整批收藏記錄，才繼續。\n\n確定要重新編號？' },
    'admin.s130': { 'zh-Hant': '已重新排序編號，請點擊「儲存全部改動」才會正式生效', 'en': 'Renumbered. Click "Save all changes" for it to take effect.', 'yue': '已重新排序編號，請點擊「儲存全部改動」才會正式生效' },
    'admin.s131': { 'zh-Hant': '已還原至上次儲存的版本', 'en': 'Reverted to the last saved version', 'yue': '已還原至上次儲存的版本' },
