    'admin.s378': { 'zh-Hant': '計分規則', 'en': 'Points rules', 'yue': '計分規則' },
    'admin.s379': { 'zh-Hant': '這裏的數值會即時影響全站學生在視訊溫習室可獲得的 PTS，修改後請先核對清楚再儲存。', 'en': 'These values immediately affect the PTS all students earn in video study rooms. Please check carefully before saving.', 'yue': '這裏的數值會即時影響全站學生在視訊溫習室可獲得的 PTS，修改後請先核對清楚再儲存。' },
    'admin.s380': { 'zh-Hant': '每專注溫習 1 分鐘可獲得的 PTS', 'en': 'PTS per minute of focused study', 'yue': '每專注溫習 1 分鐘可獲得的 PTS' },
    'admin.s381': { 'zh-Hant': '確認「仍在學習」彈窗後額外可獲得的 PTS', 'en': 'Extra PTS after confirming the "Still studying" pop-up', 'yue': '確認「仍在學習」彈窗後額外可獲得的 PTS' },
    'admin.s386': { 'zh-Hant': '載入中房間設定...', 'en': 'Loading room settings...', 'yue': '載入中房間設定...' },
