    'admin.s388': { 'zh-Hant': '（請先開放最少一個選項）', 'en': '(Please enable at least one option first)', 'yue': '（請先開放最少一個選項）' },
    'admin.s389': { 'zh-Hant': '人數上限選項', 'en': 'Room size options', 'yue': '人數上限選項' },
    'admin.s390': { 'zh-Hant': '學生建立溫習房時可選擇的人數上限（只有 2 人房及 4 人房兩種，因為視訊畫面只支援這兩種排列）。', 'en': 'Room sizes students can choose when creating a study room (only 2 or 4 people, because the video layout supports only these two).', 'yue': '學生建立溫習房時可選擇的人數上限（只有 2 人房及 4 人房兩種，因為視訊畫面只支援這兩種排列）。' },
    'admin.s391': { 'zh-Hant': '開放「2 人房」選項', 'en': 'Enable "2-person room"', 'yue': '開放「2 人房」選項' },
    'admin.s392': { 'zh-Hant': '開放「4 人房」選項', 'en': 'Enable "4-person room"', 'yue': '開放「4 人房」選項' },
    'admin.s393': { 'zh-Hant': '預設人數上限（開啟表格時預先選取）', 'en': 'Default room size (pre-selected in the form)', 'yue': '預設人數上限（開啟表格時預先選取）' },
    'admin.s394': { 'zh-Hant': '預計溫習時間選項', 'en': 'Planned study time options', 'yue': '預計溫習時間選項' },
    'admin.s395': { 'zh-Hant': '此時間只會顯示在公開大廳的房間列表，供其他同學參考，房間不會因時間到而自動結束。可自由增減分鐘選項。', 'en': 'This time only appears in the public lobby room list for other students\' reference; rooms don\'t end automatically when time is up. Add or remove minute options freely.', 'yue': '此時間只會顯示在公開大廳的房間列表，供其他同學參考，房間不會因時間到而自動結束。可自由增減分鐘選項。' },
    'admin.s396': { 'zh-Hant': '分鐘選項（以逗號分隔，例如：15, 30, 40, 45, 60）', 'en': 'Minute options (comma-separated, e.g. 15, 30, 40, 45, 60)', 'yue': '分鐘選項（以逗號分隔，例如：15, 30, 40, 45, 60）' },
    'admin.s397': { 'zh-Hant': '預設溫習時間（分鐘，開啟表格時預先選取）', 'en': 'Default study time (minutes, pre-selected in the form)', 'yue': '預設溫習時間（分鐘，開啟表格時預先選取）' },
    'admin.s398': { 'zh-Hant': '儲存房間設定', 'en': 'Save room settings', 'yue': '儲存房間設定' },
    'admin.s403': { 'zh-Hant': '「仍在溫習緊？」確認彈窗，相隔幾多分鐘出現一次', 'en': 'Interval (minutes) between "Still studying?" check pop-ups', 'yue': '「仍在溫習緊？」確認彈窗，相隔幾多分鐘出現一次' },
    'admin.s404': { 'zh-Hant': '彈窗出現之後，幾多分鐘內未確認就會暫停計分', 'en': 'Minutes without confirming after the pop-up before points pause', 'yue': '彈窗出現之後，幾多分鐘內未確認就會暫停計分' },
    'admin.s405': { 'zh-Hant': '每次開咪，最多可以連續開幾多分鐘', 'en': 'Max minutes the mic can stay on each time', 'yue': '每次開咪，最多可以連續開幾多分鐘' },
    'admin.s406': { 'zh-Hant': '開咪撞到上限之後，要冷卻（鎖住咪掣）幾多分鐘先可以再開', 'en': 'Cool-down minutes (mic locked) after hitting the mic limit', 'yue': '開咪撞到上限之後，要冷卻（鎖住咪掣）幾多分鐘先可以再開' },
    'admin.s407': { 'zh-Hant': '主動關咪、未撞到上限嘅情況下，連續幾多分鐘冇再開咪就當完全休息返、重新計過開咪時限', 'en': 'If the mic is turned off before the limit, minutes off before the mic time limit resets', 'yue': '主動關咪、未撞到上限嘅情況下，連續幾多分鐘冇再開咪就當完全休息返、重新計過開咪時限' },
    'admin.s408': { 'zh-Hant': '載入中防掛機參數設定...', 'en': 'Loading anti-idle settings...', 'yue': '載入中防掛機參數設定...' },
    'admin.s409': { 'zh-Hant': '視訊溫習室防掛機參數', 'en': 'Video room anti-idle settings', 'yue': '視訊溫習室防掛機參數' },
    'admin.s410': { 'zh-Hant': '這組數值用作防止學生掛機或開着鏡頭不理會而賺取積分，單位均為「分鐘」，請核實後才儲存。已在房內的學生不會即時生效，要待下次入房或開咪時才套用新數值。', 'en': 'These values stop students from idling or leaving the camera on to earn points. All units are minutes; please check before saving. Students already in a room are not affected until they next join or turn on the mic.', 'yue': '這組數值用作防止學生掛機或開着鏡頭不理會而賺取積分，單位均為「分鐘」，請核實後才儲存。已在房內的學生不會即時生效，要待下次入房或開咪時才套用新數值。' },
    'admin.s411': { 'zh-Hant': '所有數值都要大於 0', 'en': 'All values must be greater than 0', 'yue': '所有數值都要大於 0' },
    'admin.s412': { 'zh-Hant': '防掛機參數已儲存，即時對所有用戶生效（已在房內的學生要下次入房或開啟麥克風後才會套用新數值）！', 'en': 'Anti-idle settings saved and live for all users (students already in a room get the new values the next time they join or turn on the mic)!', 'yue': '防掛機參數已儲存，即時對所有用戶生效（已在房內的學生要下次入房或開啟麥克風後才會套用新數值）！' },
    'admin.s414': { 'zh-Hant': '確定要為所有用戶同步公開資料卡？用戶較多時可能需要一至兩分鐘。', 'en': 'Sync public profile cards for all users? It may take a minute or two with many users.', 'yue': '確定要為所有用戶同步公開資料卡？用戶較多時可能需要一至兩分鐘。' },
